package vn.vinhkhang.thuchi;
import java.util.*;
import java.time.*;
import java.time.format.*;
import java.math.*;
import java.io.*;
import java.security.*;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.http.*;
import org.springframework.jdbc.datasource.DataSourceUtils;
import org.apache.poi.ss.usermodel.*;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;

@RestController @RequestMapping("/api/import-simple")
public class SimpleImport {
 final Api api;
 final Map<String,Preview> previews=new HashMap<>();
 record Spec(String id,String title,String columns,String help){}
 record Preview(long actor,long until,String kind,List<Map<String,Object>> rows,Map<String,Object> defaults){}
 static final List<Spec> SPECS=List.of(
  new Spec("receipt","Phiếu thu","Ngày *|Nội dung *|Số tiền (đ) *|Nguồn tiền|Đối tác|Nhóm thu / chi|Nhóm thu|Mã công nợ|Nghiệp vụ|Ghi chú","Chọn nguồn tiền chung trước khi đọc file. Nhóm thu: Đại lý, Bán lẻ, Góp vốn, Vay vốn, Khác. Nghiệp vụ: Nhận tiền vay hoặc Nhà cung cấp hoàn tiền khi có liên kết. Ghi chú được lưu cùng nội dung."),
  new Spec("expense","Phiếu chi","Ngày *|Nội dung *|Số tiền (đ) *|Nguồn tiền|Đối tác|Nhóm thu / chi|Mã công nợ|Nghiệp vụ|Ghi chú","Thanh toán công nợ: điền Đối tác và Mã công nợ; nhà cung cấp trả theo tổng nợ: Nghiệp vụ = Trả nhà cung cấp. Trả gốc vay / Trả lãi vay / Chi ứng lương cần Mã công nợ. Không nhập lại khoản đã ghi sổ."),
  new Spec("transfer","Chuyển quỹ","Ngày *|Nguồn chuyển *|Nguồn nhận *|Số tiền (đ) *|Nội dung *|Phí (đ)|Ghi chú","Nguồn chuyển và nhận phải khác nhau; nguồn chuyển phải đủ cả tiền chuyển và phí."),
  new Spec("payable","Công nợ phải trả","Đối tác *|Nhóm nợ *|Ngày *|Nội dung *|Số tiền (đ) *|Hạn thanh toán|Ghi chú","Nhóm nợ: Nhà cung cấp, Vận chuyển, Vay vốn, Khác. Hạn trả có thể bỏ trống. Chỉ ghi tăng nợ; không tự chi tiền. Không nhập lại phiếu đã đồng bộ từ Kho."),
  new Spec("advance","Tạm ứng lương","Nhân viên *|Ngày *|Tháng lương *|Số tiền (đ) *|Nội dung *|Trạng thái|Nguồn tiền|Ghi chú","Trạng thái: Đề nghị ứng (mặc định) hoặc Đã chi ứng. Đã chi ứng tạo phiếu chi liên kết và cần nguồn tiền đủ số dư. Không nhập thêm phiếu chi cho cùng khoản ứng."),
  new Spec("attendance","Chấm công","Mã chấm công *|Ngày *|Công / nghỉ *|Tăng ca (giờ)|Ghi chú","Công / nghỉ: X hoặc 1 = đủ công; ½ hoặc 0,5 = nửa công; P = phép có lương; KL = nghỉ không lương; N hoặc 0 = nghỉ. Tăng ca theo bước 0,25 giờ. Tháng đã khóa hoặc ngày đã chấm không nhập đè."),
  new Spec("customer","Khách hàng / Đại lý","Tên *|Nhóm khách *|Điện thoại|Địa chỉ|Ghi chú","Nhóm khách: Đại lý hoặc Bán lẻ. Chỉ lưu thông tin khách, không tạo công nợ khách hàng."),
  new Spec("partner","Đối tác phải trả","Tên *|Loại đối tác *|Điện thoại|Địa chỉ|Ghi chú","Loại đối tác: Nhà cung cấp, Vận chuyển, Cho vay, Khác. Không nhập nhân viên vào danh sách này."),
  new Spec("investor","Người góp vốn","Tên *|Điện thoại|Địa chỉ|Ghi chú","Chỉ tạo danh sách người góp vốn. Tiền nhận thực tế ghi ở Phiếu thu."),
  new Spec("employee","Nhân viên","Tên *|Chức vụ|Mã chấm công|Điện thoại|Địa chỉ|Ghi chú","Chức vụ tự điền. Mã chấm công duy nhất, không dấu; cần mã này trước khi nhập bảng chấm công."),
  new Spec("funds","Nguồn tiền","Tên nguồn tiền *|Loại *|Ngày bắt đầu *|Số dư đầu kỳ (đ) *|Ngân hàng|Số tài khoản|Chủ tài khoản|Ghi chú","Loại: Tiền mặt, Ngân hàng, Khác. Số tài khoản và điện thoại là cột văn bản để giữ số 0 đầu. Số dư đầu kỳ không phải phiếu thu."),
  new Spec("categories","Danh mục thu / chi","Tên danh mục *|Loại *|Ghi chú","Loại: Thu, Chi, Thu và chi. Nhập danh mục và nguồn tiền trước khi nhập chứng từ.")
 );
 public SimpleImport(Api api){this.api=api;}
 @ExceptionHandler(Api.Fail.class) ResponseEntity<?> fail(Api.Fail f){return api.fail(f);}
 @ExceptionHandler(Exception.class) ResponseEntity<?> other(Exception e){return api.other(e);}
 static Spec spec(String kind){return SPECS.stream().filter(s->s.id.equals(kind)).findFirst().orElseThrow(()->new Api.Fail(400,"Mục nhập không hợp lệ"));}
 @GetMapping("/types") List<Map<String,Object>> types(HttpServletRequest r){api.actor(r);return SPECS.stream().map(s->Map.<String,Object>of("id",s.id,"title",s.title,"columns",s.columns.split("\\|"),"help",s.help)).toList();}
 @GetMapping("/template/{kind}") ResponseEntity<byte[]> template(@PathVariable String kind,HttpServletRequest r)throws Exception {api.actor(r);return ResponseEntity.ok().contentType(MediaType.parseMediaType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")).body(templateBytes(spec(kind)));}
 static byte[] templateBytes(Spec s)throws Exception {
  try(var w=new XSSFWorkbook();var out=new ByteArrayOutputStream()){
   var sheet=w.createSheet("Nhap du lieu");String[] cols=s.columns.split("\\|");
   var header=w.createCellStyle();header.setFillForegroundColor(IndexedColors.LIGHT_CORNFLOWER_BLUE.getIndex());header.setFillPattern(FillPatternType.SOLID_FOREGROUND);header.setWrapText(true);var bold=w.createFont();bold.setBold(true);header.setFont(bold);
   var plain=w.createCellStyle();plain.setDataFormat(w.createDataFormat().getFormat("@"));
   var money=w.createCellStyle();money.setDataFormat(w.createDataFormat().getFormat("#,##0"));
   for(var st:List.of(header,plain,money)){st.setBorderTop(BorderStyle.THIN);st.setBorderBottom(BorderStyle.THIN);st.setBorderLeft(BorderStyle.THIN);st.setBorderRight(BorderStyle.THIN);}
   var h=sheet.createRow(0);h.setHeightInPoints(36);
   for(int j=0;j<cols.length;j++){var c=h.createCell(j);c.setCellValue(cols[j]);c.setCellStyle(header);sheet.setColumnWidth(j,Math.min(55,cols[j].contains("Nội dung")?50:cols[j].contains("Ghi chú")?38:26)*256);sheet.setDefaultColumnStyle(j,cols[j].contains("(đ)")?money:plain);}
   for(int i=1;i<=30;i++){var row=sheet.createRow(i);for(int j=0;j<cols.length;j++){var c=row.createCell(j);c.setCellStyle(cols[j].contains("(đ)")?money:plain);}}
   sheet.createFreezePane(0,1);sheet.setAutoFilter(new org.apache.poi.ss.util.CellRangeAddress(0,30,0,cols.length-1));
   var guide=w.createSheet("Huong dan");guide.setColumnWidth(0,110*256);var gstyle=w.createCellStyle();gstyle.setWrapText(true);
   String[] lines={"MẪU NHẬP: "+s.title,"Điền dữ liệu vào sheet Nhap du lieu. Mỗi dòng là một bản ghi; không đổi tên đầu cột. Cột * bắt buộc.",s.help,"Ngày: dd/MM/yyyy (ví dụ 08/10/2026). Tháng lương: MM/yyyy (ví dụ 10/2026).","Số tiền: nhập số nguyên như 1000000; Excel hiển thị ngăn cách hàng nghìn. Không gõ chữ đ vào ô tiền.","Tên nguồn tiền / đối tác / danh mục phải khớp dữ liệu đã lưu; tên trùng sẽ yêu cầu nhập bằng #ID trong màn hình xem trước.","Không có dòng ví dụ trong sheet nhập để tránh nhập nhầm dữ liệu mẫu. Chọn file → xem trước → chọn dòng hợp lệ → xác nhận nhập.","Ảnh/PDF chứng từ được thêm sau khi nhập. Nhập Excel không thay thế sao lưu/khôi phục dữ liệu."};
   for(int i=0;i<lines.length;i++){var row=guide.createRow(i);row.setHeightInPoints(i==2?85:48);var c=row.createCell(0);c.setCellValue(lines[i]);c.setCellStyle(gstyle);}
   w.write(out);return out.toByteArray();
  }
 }
 static String key(String x){return java.text.Normalizer.normalize(x,java.text.Normalizer.Form.NFD).replaceAll("\\p{M}","").replace('đ','d').replace('Đ','D').toLowerCase(Locale.ROOT).replace("*","").trim().replaceAll("\\s+"," ");}
 static String value(Map<String,Object> row,String col){return Api.str(row,key(col));}
 static String required(Map<String,Object>row,String col){String s=value(row,col);if(s.isBlank())throw new Api.Fail(400,"Thiếu "+col);if(s.length()>2000)throw new Api.Fail(400,col+" quá dài");return s;}
 static long money(Map<String,Object> row,String col,boolean required){String s=required?required(row,col):value(row,col);if(s.isBlank())return 0;try{if(s.matches("-?\\d{1,3}(\\.\\d{3})+"))s=s.replace(".","");return new BigDecimal(s).longValueExact();}catch(Exception e){throw new Api.Fail(400,col+" phải là số nguyên (ví dụ 1000000)");}}
 static String day(Map<String,Object> row,String col,boolean needed){String s=needed?required(row,col):value(row,col);if(s.isEmpty())return "";try{if(s.matches("\\d{4}-\\d{2}-\\d{2}"))return LocalDate.parse(s).toString();return LocalDate.parse(s,DateTimeFormatter.ofPattern("d/M/uuuu").withResolverStyle(ResolverStyle.STRICT)).toString();}catch(Exception e){throw new Api.Fail(400,col+" phải là ngày hợp lệ dd/MM/yyyy");}}
 static String pick(String input,String fallback,String...pairs){if(input.isBlank())return fallback;for(int i=0;i<pairs.length;i+=2)if(key(input).equals(key(pairs[i]))||input.equals(pairs[i+1]))return pairs[i+1];throw new Api.Fail(400,"Giá trị không hợp lệ: "+input);}
 long ref(String table,String input,String filter,boolean needed){if(input.isBlank()){if(needed)throw new Api.Fail(400,"Chọn "+(table.equals("funds")?"nguồn tiền":table.equals("contacts")?"đối tác / nhân viên":"danh mục"));return 0;}List<Map<String,Object>> rows;if(input.matches("#\\d+"))rows=api.db.queryForList("SELECT * FROM "+table+" WHERE deleted=0 AND id=? "+filter,Long.parseLong(input.substring(1)));else rows=api.db.queryForList("SELECT * FROM "+table+" WHERE deleted=0 AND name=? COLLATE NOCASE "+filter,input);if(rows.size()!=1)throw new Api.Fail(400,rows.isEmpty()?"Chưa có dữ liệu: "+input:"Tên trùng: "+input+"; dùng #ID để xác định");return Api.num(rows.getFirst(),"id");}
 Map<String,Object> convert(String kind,Map<String,Object> row,Map<String,Object> defaults){var b=new LinkedHashMap<String,Object>();b.put("note",value(row,"Ghi chú"));b.put("description",value(row,"Nội dung"));b.put("amount",money(row,"Số tiền (đ)",List.of("receipt","expense","transfer","payable","advance").contains(kind)));if(List.of("receipt","expense","transfer","payable","advance","attendance").contains(kind))b.put("date",day(row,"Ngày",true));
  String note=value(row,"Ghi chú");if(!note.isBlank()&&!Api.str(b,"description").isBlank())b.put("description",Api.str(b,"description")+" · "+note);
  switch(kind){
   case "receipt","expense","transfer"->{b.put("type",kind.equals("receipt")?"RECEIPT":kind.equals("expense")?"EXPENSE":"TRANSFER");String fund=value(row,kind.equals("transfer")?"Nguồn chuyển":"Nguồn tiền");if(fund.isBlank())fund=Api.str(defaults,"fund");b.put("fund_id",ref("funds",fund,"",true));b.put("to_fund_id",kind.equals("transfer")?ref("funds",required(row,"Nguồn nhận"),"",true):0);b.put("fee",money(row,"Phí (đ)",false));String cat=value(row,"Nhóm thu / chi");if(cat.isBlank())cat=Api.str(defaults,"category");b.put("category_id",ref("categories",cat,"",false));b.put("contact_id",ref("contacts",value(row,"Đối tác"),"",false));String ob=value(row,"Mã công nợ");if(!ob.isEmpty()){var obs=api.db.queryForList("SELECT * FROM obligations WHERE deleted=0 AND code=? COLLATE NOCASE",ob);if(obs.size()!=1)throw new Api.Fail(400,"Mã công nợ không tồn tại: "+ob);b.put("obligation_id",obs.getFirst().get("id"));}
    b.put("purpose",pick(value(row,"Nghiệp vụ"),"","Trả nhà cung cấp","SUPPLIER_PAYMENT","Nhà cung cấp hoàn tiền","SUPPLIER_REFUND","Nhận tiền vay","LOAN_RECEIVE","Trả gốc vay","LOAN_PRINCIPAL","Trả lãi vay","LOAN_INTEREST","Chi ứng lương","ADVANCE_ISSUE","Hoàn ứng lương","ADVANCE_RETURN"));b.put("receipt_group",pick(value(row,"Nhóm thu"),"OTHER","Đại lý","DEALER","Bán lẻ","RETAIL","Góp vốn","CAPITAL","Vay vốn","BORROWING","Khác","OTHER"));}
   case "payable","advance"->{b.put("kind",kind.equals("advance")?"ADVANCE":"PAYABLE");String group=kind.equals("advance")?"SUPPLIER":pick(required(row,"Nhóm nợ"),"","Nhà cung cấp","SUPPLIER","Vận chuyển","CARRIER","Vay vốn","LOAN","Khác","OTHER");b.put("debt_group",group);b.put("contact_id",ref("contacts",required(row,kind.equals("advance")?"Nhân viên":"Đối tác"),kind.equals("advance")?"AND kind='EMPLOYEE'":"AND kind IN ('SUPPLIER','OTHER') AND party_type<>'INVESTOR'",true));b.put("due_date",day(row,"Hạn thanh toán",false));if(kind.equals("advance")){String m=required(row,"Tháng lương");try{b.put("salary_month",YearMonth.parse(m,m.matches("\\d{4}-\\d{2}")?DateTimeFormatter.ofPattern("uuuu-MM"):DateTimeFormatter.ofPattern("M/uuuu")).toString());}catch(Exception e){throw new Api.Fail(400,"Tháng lương phải là MM/yyyy");}b.put("issue",pick(value(row,"Trạng thái"),"REQUEST","Đề nghị ứng","REQUEST","Đã chi ứng","ISSUED"));if(b.get("issue").equals("ISSUED")){String fund=value(row,"Nguồn tiền");if(fund.isBlank())fund=Api.str(defaults,"fund");b.put("fund_id",ref("funds",fund,"",true));}}else {var c=api.one("contacts",Api.num(b,"contact_id"));String expected=group.equals("SUPPLIER")?"SUPPLIER":group.equals("CARRIER")?"CARRIER":group.equals("LOAN")?"LENDER":"OTHER";if(!Api.str(c,"party_type").equals(expected))throw new Api.Fail(400,"Loại đối tác không khớp nhóm nợ");}}
   case "attendance"->{String code=required(row,"Mã chấm công");var employees=api.db.queryForList("SELECT * FROM contacts WHERE deleted=0 AND kind='EMPLOYEE' AND attendance_code=? COLLATE NOCASE",code);if(employees.size()!=1)throw new Api.Fail(400,"Không tìm thấy mã chấm công: "+code);b.put("employee_id",employees.getFirst().get("id"));b.put("status",pick(required(row,"Công / nghỉ"),"","X","WORK","1","WORK","½","HALF","0,5","HALF","0.5","HALF","P","PAID_LEAVE","KL","UNPAID_LEAVE","N","OFF","0","OFF"));try{String hours=value(row,"Tăng ca (giờ)").replace(',','.');b.put("overtime_minutes",hours.isBlank()?0:new BigDecimal(hours).multiply(BigDecimal.valueOf(60)).longValueExact());}catch(Exception e){throw new Api.Fail(400,"Tăng ca phải là số giờ, ví dụ 0,25");}}
   case "funds"->{b.put("name",required(row,"Tên nguồn tiền"));b.put("kind",pick(required(row,"Loại"),"","Tiền mặt","CASH","Ngân hàng","BANK","Khác","OTHER"));b.put("opening_date",day(row,"Ngày bắt đầu",true));b.put("opening",money(row,"Số dư đầu kỳ (đ)",true));b.put("bank_name",value(row,"Ngân hàng"));b.put("account_number",value(row,"Số tài khoản"));b.put("account_holder",value(row,"Chủ tài khoản"));}
   case "categories"->{b.put("name",required(row,"Tên danh mục"));b.put("kind",pick(required(row,"Loại"),"","Thu","IN","Chi","OUT","Thu và chi","BOTH"));}
   default->{b.put("name",required(row,"Tên"));b.put("phone",value(row,"Điện thoại"));b.put("address",value(row,"Địa chỉ"));b.put("kind",kind.equals("customer")?"CUSTOMER":kind.equals("employee")?"EMPLOYEE":"OTHER");b.put("customer_type",kind.equals("customer")?pick(required(row,"Nhóm khách"),"","Đại lý","DEALER","Bán lẻ","RETAIL"):"RETAIL");String party=kind.equals("investor")?"INVESTOR":kind.equals("partner")?pick(required(row,"Loại đối tác"),"","Nhà cung cấp","SUPPLIER","Vận chuyển","CARRIER","Cho vay","LENDER","Khác","OTHER"):"OTHER";b.put("party_type",party);if(party.equals("SUPPLIER"))b.put("kind","SUPPLIER");b.put("job_title",value(row,"Chức vụ"));b.put("attendance_code",value(row,"Mã chấm công"));}
  }
  return b;
 }
 static String table(String kind){return switch(kind){case "receipt","expense","transfer"->"vouchers";case "payable","advance"->"obligations";case "attendance"->"attendance";case "funds","categories"->kind;default->"contacts";};}
 String fingerprint(String kind,Map<String,Object>b)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest((kind+api.serialize(new TreeMap<>(b))).getBytes(java.nio.charset.StandardCharsets.UTF_8)));}
 void duplicate(String kind,Map<String,Object>b,String hash){String table=table(kind);if(api.db.queryForObject("SELECT COUNT(*) FROM audit a JOIN "+table+" t ON t.id=a.entity_id WHERE a.entity=? AND a.action='IMPORT_EXCEL' AND a.reason=? AND t.deleted=0",Integer.class,table,hash)>0)throw new Api.Fail(409,"Dòng đã nhập từ Excel trước đó");int n;
  if(table.equals("vouchers"))n=api.db.queryForObject("SELECT COUNT(*) FROM vouchers WHERE deleted=0 AND type=? AND date=? AND description=? AND amount=? AND fund_id=? AND COALESCE(contact_id,0)=?",Integer.class,b.get("type"),b.get("date"),b.get("description"),b.get("amount"),b.get("fund_id"),Api.num(b,"contact_id"));
  else if(table.equals("obligations"))n=api.db.queryForObject("SELECT COUNT(*) FROM obligations WHERE deleted=0 AND kind=? AND contact_id=? AND date=? AND amount=? AND debt_group=?",Integer.class,b.get("kind"),b.get("contact_id"),b.get("date"),b.get("amount"),b.get("debt_group"));
  else if(table.equals("attendance"))n=api.db.queryForObject("SELECT COUNT(*) FROM attendance WHERE employee_id=? AND date=?",Integer.class,b.get("employee_id"),b.get("date"));
  else if(table.equals("contacts"))n=api.db.queryForObject("SELECT COUNT(*) FROM contacts WHERE deleted=0 AND name=? COLLATE NOCASE AND kind=? AND party_type=?",Integer.class,b.get("name"),b.get("kind"),b.get("party_type"));
  else n=api.db.queryForObject("SELECT COUNT(*) FROM "+table+" WHERE deleted=0 AND name=? COLLATE NOCASE",Integer.class,b.get("name"));
  if(n>0)throw new Api.Fail(409,"Nghi trùng dữ liệu đã có; kiểm tra trong app trước khi nhập");
 }
 Map<String,Object> save(String kind,Map<String,Object>b,HttpServletRequest r,long actor)throws Exception {String hash=fingerprint(kind,b);duplicate(kind,b,hash);String table=table(kind);Map<String,Object> saved;
  switch(table){case "vouchers"->saved=api.saveVoucher(0,b,actor);case "obligations"->{saved=api.saveObligation(0,b,actor);if(kind.equals("advance")&&Api.str(b,"issue").equals("ISSUED")){var v=new LinkedHashMap<String,Object>(b);v.put("type","EXPENSE");v.put("purpose","ADVANCE_ISSUE");v.put("obligation_id",saved.get("id"));api.saveVoucher(0,v,actor);}}case "attendance"->saved=api.saveAttendance(b,r);default->saved=api.saveMaster(table,0,b,actor);}
  api.audit(actor,"IMPORT_EXCEL",table,Api.num(saved,"id"),null,Map.of("kind",kind,"data",b),hash);return saved;
 }
 List<Map<String,Object>> read(MultipartFile file,String kind)throws Exception {
  if(file.isEmpty()||file.getSize()>10*1024*1024||!String.valueOf(file.getOriginalFilename()).toLowerCase(Locale.ROOT).endsWith(".xlsx"))throw new Api.Fail(400,"Chọn file .xlsx không quá 10 MB");
  try(var w=WorkbookFactory.create(file.getInputStream())){var sheet=w.getSheet("Nhap du lieu");if(sheet==null)sheet=w.getSheetAt(0);if(sheet.getLastRowNum()>5000)throw new Api.Fail(400,"File quá nhiều dòng; tối đa 500 dòng dữ liệu mỗi lần");var fmt=new DataFormatter(Locale.US);var header=sheet.getRow(0);if(header==null)throw new Api.Fail(400,"Thiếu đầu cột ở dòng 1");if(header.getLastCellNum()>40)throw new Api.Fail(400,"Quá nhiều cột");var columns=new HashMap<Integer,String>();var seen=new HashSet<String>();for(var c:header){String h=key(fmt.formatCellValue(c));if(h.isBlank())continue;if(!seen.add(h))throw new Api.Fail(400,"Trùng tên đầu cột: "+h);columns.put(c.getColumnIndex(),h);}for(String col:spec(kind).columns.split("\\|"))if(col.contains("*")&&!columns.containsValue(key(col)))throw new Api.Fail(400,"Thiếu cột: "+col);
   var rows=new ArrayList<Map<String,Object>>();for(int i=1;i<=sheet.getLastRowNum();i++){var row=sheet.getRow(i);if(row==null)continue;var raw=new LinkedHashMap<String,Object>();String issue="";for(var e:columns.entrySet()){var cell=row.getCell(e.getKey());String v="";if(cell!=null){if(cell.getCellType()==CellType.FORMULA)issue="Không nhận công thức; dán giá trị trước khi nhập";else if(cell.getCellType()==CellType.NUMERIC){if(DateUtil.isCellDateFormatted(cell))v=cell.getLocalDateTimeCellValue().toLocalDate().toString();else v=BigDecimal.valueOf(cell.getNumericCellValue()).stripTrailingZeros().toPlainString();}else v=fmt.formatCellValue(cell).trim();if(v.length()>2000)issue="Ô dữ liệu quá dài";}raw.put(e.getValue(),v);}if(raw.values().stream().allMatch(v->v.toString().isBlank()))continue;rows.add(new LinkedHashMap<>(Map.of("line",i+1,"raw",raw,"error",issue)));if(rows.size()>500)throw new Api.Fail(400,"Tối đa 500 dòng mỗi lần nhập");}if(rows.isEmpty())throw new Api.Fail(400,"File chưa có dữ liệu; điền dữ liệu vào sheet Nhap du lieu");return rows;
  }
 }
 @PostMapping("/preview/{kind}") Map<String,Object> preview(@PathVariable String kind,@RequestParam MultipartFile file,@RequestParam(defaultValue="")String fund,@RequestParam(defaultValue="")String category,HttpServletRequest r)throws Exception {
  synchronized(api){long actor=api.actor(r);spec(kind);var rows=read(file,kind);var defaults=Map.<String,Object>of("fund",fund,"category",category);var converted=new HashMap<Integer,Map<String,Object>>();for(var row:rows){if(!Api.str(row,"error").isBlank())continue;try{@SuppressWarnings("unchecked") var raw=(Map<String,Object>)row.get("raw");converted.put((int)Api.num(row,"line"),convert(kind,raw,defaults));}catch(Api.Fail e){row.put("error",e.getMessage());}}
   var ordered=new ArrayList<>(rows);ordered.sort(Comparator.comparing(row->Api.str(converted.getOrDefault((int)Api.num(row,"line"),Map.of()),"date")));
   api.tx.executeWithoutResult(tx->{var connection=DataSourceUtils.getConnection(api.db.getDataSource());for(var row:ordered){if(!Api.str(row,"error").isBlank())continue;java.sql.Savepoint point=null;try{point=connection.setSavepoint();save(kind,converted.get((int)Api.num(row,"line")),r,actor);connection.releaseSavepoint(point);row.put("valid",true);}catch(Exception e){try{if(point!=null){connection.rollback(point);connection.releaseSavepoint(point);}}catch(Exception x){throw new IllegalStateException(x);}row.put("error",e instanceof Api.Fail?e.getMessage():"Dữ liệu không hợp lệ; kiểm tra lại dòng này");}}tx.setRollbackOnly();});
   previews.entrySet().removeIf(e->e.getValue().until<System.currentTimeMillis());if(previews.size()>50)throw new Api.Fail(429,"Quá nhiều lượt xem trước; thử lại sau");String ticket=UUID.randomUUID().toString();previews.put(ticket,new Preview(actor,System.currentTimeMillis()+1200000,kind,rows,defaults));return Map.of("ticket",ticket,"rows",rows,"columns",spec(kind).columns.split("\\|"),"count",rows.size());
  }
 }
 @PostMapping("/commit") Map<String,Object> commit(@RequestBody Map<String,Object>b,HttpServletRequest r)throws Exception {synchronized(api){long actor=api.actor(r);String ticket=Api.required(b,"ticket");var p=previews.get(ticket);if(p==null||p.actor!=actor||p.until<System.currentTimeMillis())throw new Api.Fail(409,"Bản xem trước đã hết hạn; chọn file lại");if(!(b.get("lines") instanceof List<?> lines)||lines.isEmpty()||lines.size()>500)throw new Api.Fail(400,"Chọn từ 1 đến 500 dòng hợp lệ");var wanted=new HashSet<Long>();for(Object line:lines){try{if(!wanted.add(new BigDecimal(line.toString()).longValueExact()))throw new Exception();}catch(Exception e){throw new Api.Fail(400,"Dòng được chọn không hợp lệ");}}var rows=p.rows.stream().filter(row->wanted.contains(Api.num(row,"line"))).toList();if(rows.size()!=wanted.size()||rows.stream().anyMatch(row->!Boolean.TRUE.equals(row.get("valid"))))throw new Api.Fail(400,"Chỉ chọn dòng hợp lệ");var data=new ArrayList<Map<String,Object>>();for(var row:rows){@SuppressWarnings("unchecked") var raw=(Map<String,Object>)row.get("raw");data.add(convert(p.kind,raw,p.defaults));}data.sort(Comparator.comparing(row->Api.str(row,"date")));api.createBackup();var result=api.tx.execute(tx->{int count=0;for(var row:data){try{save(p.kind,row,r,actor);count++;}catch(Api.Fail e){throw new Api.Fail(e.status,"Dữ liệu đã thay đổi hoặc có lỗi: "+e.getMessage()+". Chưa nhập dòng nào; xem trước lại.");}catch(Exception e){throw new IllegalStateException(e);}}return Map.<String,Object>of("count",count);});previews.remove(ticket);return result;}}
}
